def add(items, title):
    if not title or not str(title).strip():
        raise ValueError("title must not be empty")
    items.append({"title": title, "done": False})
    return items

def done(items, i):
    if not -len(items) <= i < len(items):
        raise IndexError(f"index {i} out of range for {len(items)} item(s)")
    items[i]["done"] = True
